def merge_sort(xs):
    if len(xs) <= 1:
        return list(xs)
    orta = len(xs) // 2
    sol = merge_sort(xs[:orta])
    sag = merge_sort(xs[orta:])
    return birlestir(sol, sag)


def birlestir(sol, sag):
    sonuc = []
    i = j = 0
    while i < len(sol) and j < len(sag):
        if sol[i] <= sag[j]:
            sonuc.append(sol[i])
            i += 1
        else:
            sonuc.append(sag[j])
            j += 1
    sonuc.extend(sol[i:])
    sonuc.extend(sag[j:])
    return sonuc
